    internal data class ScrollerRecipeMessage(
        val id: String,
        val user: Boolean,
        val text: String,
        val anchor: Boolean =
            user,
    )

    @Composable
    internal fun ScrollerRecipeTranscript(
        messages: List<ScrollerRecipeMessage>,
        animateUsers: Boolean = false,
    ) {
        messages.forEach { message ->
            key(message.id) {
                MessageScrollerItem(Modifier.testTag(message.id), messageId = message.id, scrollAnchor = message.anchor) {
                    var entered by remember { mutableStateOf(false) }
                    val progress =
                        animateFloatAsState(
                            if (!animateUsers || !message.user || entered) 1f else 0f,
                            tween(260, easing = CubicBezierEasing(0.16f, 1f, 0.3f, 1f)),
                            label = "message-slide-up",
                        )
                    LaunchedEffect(Unit) { entered = true }
                    Message(
                        modifier =
                            Modifier.graphicsLayer {
                                alpha = progress.value
                                translationY = 10.dp.toPx() * (1f - progress.value)
                            },
                        align = if (message.user) MessageAlign.End else MessageAlign.Start,
                    ) {
                        Bubble(variant = if (message.user) BubbleVariant.Muted else BubbleVariant.Ghost) {
                            BubbleContent {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    message.text.split("\n\n").filter { it.isNotBlank() }.forEach { paragraph ->
                                        Text { paragraph }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    @Composable
    internal fun ScrollerRecipeFrame(
        title: String,
        description: String,
        note: String,
        modifier: Modifier = Modifier,
        action: (@Composable () -> Unit)? = null,
        footer: (@Composable () -> Unit)? = null,
        transcript: @Composable () -> Unit,
    ) {
        val border = currentTheme.colors.border
        val muted = currentTheme.colors.mutedForeground
        val nova = currentTheme.activePreset == StylePreset.Nova
        Column(
            modifier.widthIn(max = 384.dp).fillMaxWidth(),
            verticalArrangement = Arrangement.spacedBy(16.dp),
            horizontalAlignment = Alignment.CenterHorizontally,
        ) {
            Card(Modifier.fillMaxWidth().height(560.dp).testTag("scroller-recipe-card"), spacing = 0.dp) {
                CardHeader(
                    Modifier.drawBehind {
                        drawLine(
                            border,
                            Offset(
                                0f,
                                size.height - 0.5.dp.toPx(),
                            ),
                            Offset(
                                size.width,
                                size.height - 0.5.dp.toPx(),
                            ),
                            1.dp.toPx(),
                        )
                    }
                        .padding(16.dp),
                ) {
                    CardTitle(title)
                    CardDescription(description)
                    if (action != null) CardAction { action() }
                }
                Box(
                    Modifier.fillMaxWidth().weight(1f).padding(
                        bottom =
                            if (footer == null) {
                                16.dp
                            } else {
                                0.dp
                            },
                    ),
                ) { transcript() }
                if (footer != null) {
                    CardFooter(
                        modifier =
                            if (nova) {
                                Modifier
                            } else {
                                Modifier.drawBehind {
                                    drawLine(
                                        border,
                                        Offset(0f, 0.5.dp.toPx()),
                                        Offset(size.width, 0.5.dp.toPx()),
                                        1.dp.toPx(),
                                    )
                                }
                            },
                        style = Style { contentPadding(16.dp) },
                    ) {
                        Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) { footer() }
                    }
                }
            }
            Text(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 2.dp),
                textStyle = TextStyle(color = muted, fontSize = 12.sp, lineHeight = 16.sp, textAlign = TextAlign.Center),
            ) { note }
        }
    }

    private val scrollerStatusMessages =
        List(12) { index ->
            val user = index % 2 == 0
            val number = index + 1
            ScrollerRecipeMessage(
                "scrollable-${'$'}number",
                user,
                if (user) {
                    "Review scroll checkpoint ${'$'}number."
                } else {
                    "Checkpoint ${'$'}number is synced. The scrollable hook updates as the viewport moves.\n\n" +
                        (
                            "When the reader is at the first message, the footer should " +
                                "only point them down. Once they move into the middle of the " +
                                "transcript, it should explain that both directions are " +
                                "available.\n\n"
                        ) +
                        "At the latest message, the footer should switch again and only point them back up."
                },
            )
        }

    @Composable
    internal fun MessageScrollerScrollableRecipe(modifier: Modifier = Modifier) {
        val state = rememberMessageScrollerState(defaultScrollPosition = MessageScrollerPosition.Start)
        val muted = currentTheme.colors.mutedForeground
        MessageScrollerProvider(state) {
            ScrollerRecipeFrame(
                "Scroll Status",
                "Where the reader can go scroll to based on current scroll position.",
                "Scroll the transcript to see the footer update.",
                modifier,
                footer = {
                    val scrollable = messageScrollerScrollable()
                    val status =
                        when {
                            scrollable.start && scrollable.end -> "You can scroll both ways."
                            scrollable.end -> "You are at the top. You can only scroll down."
                            scrollable.start -> "You are at the bottom. You can only scroll up."
                            else -> "All messages fit in the viewport."
                        }
                    Text(textStyle = TextStyle(color = muted, textAlign = TextAlign.Center)) { status }
                },
            ) {
                MessageScroller {
                    MessageScrollerViewport(Modifier.testTag("scrollable-viewport")) {
                        MessageScrollerContent(Modifier.padding(16.dp), spacing = 16.dp) {
                            ScrollerRecipeTranscript(scrollerStatusMessages, animateUsers = true)
                        }
                    }
                    MessageScrollerButton()
                }
            }
        }
    }
    """.trimIndent()

