            }
        }
    }

    @Composable
    private fun ScrollerTranscriptOutline() {
        val state = messageScrollerState()
        val current = messageScrollerVisibility().currentAnchorId
        val scope = rememberCoroutineScope()
        val colors = currentTheme.colors
        val triggerStyle =
            remember {
                Style {
                    width(36.dp)
                    height(36.dp)
                    contentPadding(0.dp)
                    shape(RoundedCornerShape(6.dp))
                }
            }
        val panelStyle =
            remember {
                Style {
                    contentPadding(4.dp)
                    shape(RoundedCornerShape(16.dp))
                }
            }
        HoverCard {
            HoverCardTrigger {
                Button(
                    onClick =
                        {},
                    label =
                        "Open transcript outline",
                    variant =
                        ButtonVariant.Ghost,
                    style =
                    triggerStyle,
                ) {
                    Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                        scrollerVisibilityMessages.filter { it.user }.forEach { message ->
                            val color =
                                if (current == message.id) {
                                    colors.foreground
                                } else {
                                    colors.mutedForeground.copy(
                                        alpha =
                                            colors.mutedForeground.alpha * 0.4f,
                                    )
                                }
                            Box(Modifier.width(16.dp).height(2.dp).background(color, RoundedCornerShape(50)))
                        }
                    }
                }
            }
            HoverCardContent(
                side = HoverCardSide.Left,
                modifier = Modifier.width(256.dp).testTag("transcript-outline-panel"),
                sideOffset = (-28).dp,
                align = PopupAlign.Center,
                style = panelStyle,
            ) {
                Column(verticalArrangement = Arrangement.spacedBy(4.dp)) {
                    scrollerVisibilityMessages.filter { it.user }.forEach { message ->
                        val isCurrent = current == message.id
                        val rowStyle =
                            remember(colors, isCurrent) {
                                Style {
                                    height(32.dp)
                                    borderWidth(0.dp)
                                    contentPadding(horizontal = 8.dp, vertical = 6.dp)
                                    shape(RoundedCornerShape(12.dp))
                                    background(if (isCurrent) colors.accent else Color.Transparent)
                                    hovered { background(colors.accent) }
                                    focused {
                                        background(colors.accent)
                                        dropShadow(
                                            Shadow(
                                                radius =
                                                    0.dp,
                                                color =
                                                    Color.Transparent,
                                            ),
                                        )
                                    }
                                }
                            }
                        val label = if (message.text.length > 42) message.text.take(39) + "..." else message.text
                        Button(
                            onClick = {
                                scope.launch {
                                    state.scrollToMessage(
                                        message.id,
                                        behavior =
                                            MessageScrollerScrollBehavior.Smooth,
                                    )
                                }
                            },
                            modifier =
                                Modifier.fillMaxWidth().testTag("outline-" + message.id).semantics {
                                    selected = isCurrent
                                    if (isCurrent) stateDescription = "Current location"
                                },
                            variant = ButtonVariant.Ghost,
                            style = rowStyle,
                        ) {
                            Text(
                                Modifier.fillMaxWidth(),
                                maxLines = 1,
                                overflow = TextOverflow.Ellipsis,
                                textStyle = TextStyle(fontWeight = FontWeight.Normal),
                            ) { label }
                        }
                    }
                }
            }
        }
    }
    """.trimIndent()

