                        animateFloatAsState(
                            if (!animateUsers || !message.user || entered) 1f else 0f,
                            tween(260, easing = CubicBezierEasing(0.16f, 1f, 0.3f, 1f)),
                            label = "message-slide-up",
                        )
                    LaunchedEffect(Unit) { entered = true }
                    Message(
                        modifier =
                            Modifier.graphicsLayer {
                                alpha = progress.value
                                translationY = 10.dp.toPx() * (1f - progress.value)
                            },
                        align = if (message.user) MessageAlign.End else MessageAlign.Start,
                    ) {
                        Bubble(variant = if (message.user) BubbleVariant.Muted else BubbleVariant.Ghost) {
                            BubbleContent {
                                Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                                    message.text.split("\n\n").filter { it.isNotBlank() }.forEach { paragraph ->
                                        Text { paragraph }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

