    internal fun MessageScrollerHistoryRecipe(
        modifier: Modifier = Modifier,
        toast: ToastState? = null,
    ) {
        var count by remember { mutableIntStateOf(5) }
        var reset by remember { mutableIntStateOf(0) }
        val state = rememberMessageScrollerState()
        val notifications = toast ?: rememberToastState()
        val muted = currentTheme.colors.mutedForeground
        Box(modifier.widthIn(max = 384.dp).fillMaxWidth()) {
            MessageScrollerProvider(state) {
                ScrollerRecipeFrame(
                    "Load History",
                    "Prepended messages keep your place.",
