                                    enabled = count != 5,
                                    label =
                                        "Reset loaded messages",
                                    variant =
                                        ButtonVariant.Outline,
                                    size =
                                        ButtonSize.Icon,
                                ) {
                                    Icon(Lucide.RotateCw, contentDescription = null, modifier = Modifier.size(16.dp))
                                }
