    @Composable
    internal fun MessageScrollerPreviousContextRecipe(modifier: Modifier = Modifier) {
        var reset by remember { mutableIntStateOf(0) }
        var peek by remember { mutableIntStateOf(64) }
        key(reset) {
            val messages =
                remember { mutableStateListOf<ScrollerRecipeMessage>().apply { addAll(scrollerContextMessages.take(2)) } }
            var busy by remember { mutableStateOf(false) }
            val scope = rememberCoroutineScope()
            val state = rememberMessageScrollerState(scrollMargin = 24.dp, scrollPreviousItemPeek = peek.dp)
            val nextIndex = messages.count { it.user } * 2
            val next = scrollerContextMessages.getOrNull(nextIndex)
            val muted = currentTheme.colors.mutedForeground
            val addonStyle = remember { Style { contentPaddingTop(4.dp) } }

            fun send() {
                if (busy || next == null) return
                busy = true
                messages.add(next)
                scope.launch {
                    try {
                        delay(1000)
                        val response = scrollerContextMessages[nextIndex + 1]
                        messages.add(response.copy(text = ""))
                        var accumulated = ""
                        Regex("\\S+\\s*").findAll(response.text).forEach { word ->
                            delay(35)
                            accumulated += word.value
                            messages[messages.lastIndex] = response.copy(text = accumulated)
                        }
                    } finally {
                        busy = false
                    }
                }
            }
            MessageScrollerProvider(state) {
                ScrollerRecipeFrame(
                    "Keeping Context Visible",
                    "New turns keep part of the previous reply in view.",
                    "Adjust the slider and send. Observe the previous message peak",
                    modifier,
                    action = {
                        Tooltip {
                            TooltipTrigger(disabled = busy) {
                                Button(
                                    onClick = {
                                        peek = 64
                                        reset++
                                    },
                                    enabled = !busy,
                                    label =
                                        "Reset context example",
                                    variant =
                                        ButtonVariant.Outline,
                                    size =
                                        ButtonSize.Icon,
                                ) {
                                    Icon(Lucide.RotateCw, contentDescription = null, modifier = Modifier.size(16.dp))
                                }
                            }
                            TooltipContent("Reset")
                        }
                    },
                    footer = {
                        InputGroup {
                            Box(Modifier.fillMaxWidth().height(56.dp).padding(horizontal = 12.dp, vertical = 10.dp)) {
                                Text(
                                    modifier =
                                        Modifier.wrapContentHeight(Alignment.Top, unbounded = true)
                                            .graphicsLayer { alpha = if (busy) 0.6f else 1f },
                                    maxLines = 2,
                                    overflow = TextOverflow.Ellipsis,
                                    textStyle = if (next == null) TextStyle(color = muted) else TextStyle.Default,
                                ) {
                                    next?.text ?: "No messages queued. Reset the context."
                                }
                            }
                            InputGroupAddon(InputGroupAddonAlign.BlockEnd, style = addonStyle) {
                                DropdownMenu {
                                    DropdownMenuTrigger {
                                        InputGroupButton(
                                            onClick = toggle,
                                            size = InputGroupButtonSize.IconSm,
                                            variant = ButtonVariant.Outline,
                                            label = "Add files",
                                        ) {
                                            Icon(Lucide.Plus, contentDescription = null, modifier = Modifier.size(16.dp))
                                        }
                                    }
                                    DropdownMenuContent(
                                        Modifier.width(176.dp),
                                        side =
                                            PopupPlacement.Top,
                                        align =
                                            PopupAlign.Start,
                                    ) {
                                        listOf(
                                            "Add Photos & Files" to Lucide.Paperclip,
                                            "Create Image" to Lucide.Image,
                                            "Deep Research" to Lucide.Telescope,
                                            "Web Search" to Lucide.Globe,
                                        ).forEachIndexed { index, (label, icon) ->
                                            if (index == 1) DropdownMenuSeparator()
                                            DropdownMenuItem(label, onClick = {}, content = {
                                                Row(
                                                    verticalAlignment = Alignment.CenterVertically,
                                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                                ) {
                                                    Icon(icon, modifier = Modifier.size(16.dp), contentDescription = null)
                                                    Text { label }
                                                }
                                            })
                                        }
                                    }
                                }
                                Row(
                                    Modifier.width(112.dp),
                                    verticalAlignment = Alignment.CenterVertically,
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                ) {
                                    Text(
                                        textStyle =
                                            TextStyle(
                                                color = muted,
                                                fontSize = 12.sp,
                                                lineHeight = 16.sp,
                                                fontWeight = FontWeight.Normal,
                                            ),
                                    ) { "${'$'}{peek}px" }
                                    Slider(
                                        peek.toFloat(),
                                        { peek = it.toInt() },
                                        modifier = Modifier.weight(1f),
                                        valueRange = 64f..128f,
                                        step = 1f,
                                        enabled = !busy,
                                        label = "Previous context peek",
                                    )
                                }
                                Spacer(Modifier.weight(1f))
                                InputGroupButton(
                                    onClick = ::send,
                                    enabled = next != null && !busy,
                                    size = InputGroupButtonSize.IconSm,
                                    variant = ButtonVariant.Default,
                                    label = "Send",
                                ) {
                                    Icon(Lucide.ArrowUp, contentDescription = null, modifier = Modifier.size(16.dp))
                                }
                            }
                        }
                    },
                ) {
                    MessageScroller {
                        MessageScrollerViewport(Modifier.testTag("context-viewport")) {
                            MessageScrollerContent(Modifier.padding(16.dp)) {
                                ScrollerRecipeTranscript(
                                    messages,
                                    animateUsers =
                                    true,
                                )
                            }
                        }
                        MessageScrollerButton()
                    }
                }
            }
        }
    }
